{"command": "create", "path": "/app/solution.py", "security_risk": "MEDIUM", "summary": "Create dialogue script parser and graph exporter", "file_text": "import json
import re
from collections import deque
from typing import Dict, List, Tuple


_SECTION_RE = re.compile(r"^\[(?P<id>[^\]]+)\]\s*$")


def _split_transition(line: str) -> Tuple[str, str]:
    if "->" not in line:
        raise ValueError(f"Missing transition arrow '->' in line: {line!r}")
    left, right = line.rsplit("->", 1)
    return left.strip(), right.strip()


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections_in_order: List[str] = []
    section_lines: Dict[str, List[str]] = {}

    current: str | None = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue

        m = _SECTION_RE.match(line)
        if m:
            current = m.group("id").strip()
            if current in section_lines:
                raise ValueError(f"Duplicate section header: [{current}]")
            sections_in_order.append(current)
            section_lines[current] = []
            continue

        if current is None:
            raise ValueError(f"Content before first section header: {line!r}")
        section_lines[current].append(line)

    if not sections_in_order:
        return {"nodes": [], "edges": []}

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    all_defined = set(sections_in_order)
    referenced_targets: set[str] = set()

    for sec_id in sections_in_order:
        lines = section_lines.get(sec_id, [])
        nonempty = [l for l in lines if l.strip()]
        if not nonempty:
            nodes.append({"id": sec_id, "text": "", "speaker": "", "type": "line"})
            continue

        is_choice = bool(re.match(r"^\d+\.", nonempty[0]))

        if is_choice:
            nodes.append({"id": sec_id, "text": "", "speaker": "", "type": "choice"})
            for choice_line in nonempty:
                left, target = _split_transition(choice_line)
                referenced_targets.add(target)
                edges.append({"from": sec_id, "to": target, "text": left.strip()})
        else:
            if len(nonempty) != 1:
                raise ValueError(
                    f"Section [{sec_id}] mixes multiple non-choice lines; unsupported: {nonempty!r}"
                )
            left, target = _split_transition(nonempty[0])
            referenced_targets.add(target)

            if ":" not in left:
                raise ValueError(f"Dialogue line missing speaker ':' in section [{sec_id}]: {left!r}")
            speaker, text_part = left.split(":", 1)
            speaker = speaker.strip()
            text_part = text_part.strip()

            nodes.append({"id": sec_id, "text": text_part, "speaker": speaker, "type": "line"})
            edges.append({"from": sec_id, "to": target, "text": ""})

    missing_targets = sorted(t for t in referenced_targets if t not in all_defined)
    if missing_targets:
        if missing_targets != ["End"]:
            raise ValueError(
                "Edges point to missing sections (only 'End' may be implicit): "
                + ", ".join(missing_targets)
            )
        nodes.append({"id": "End", "text": "", "speaker": "", "type": "line"})
        all_defined.add("End")

    graph = {"nodes": nodes, "edges": edges}
    _validate_graph(graph, start_id=sections_in_order[0])
    return graph


def _validate_graph(graph: Dict[str, List[Dict[str, str]]], start_id: str) -> None:
    node_ids = [n.get("id") for n in graph.get("nodes", [])]
    if any(not nid for nid in node_ids):
        raise ValueError("All nodes must have a non-empty 'id'")

    if len(set(node_ids)) != len(node_ids):
        dupes = sorted({x for x in node_ids if node_ids.count(x) > 1})
        raise ValueError(f"Duplicate node ids: {dupes}")

    node_set = set(node_ids)

    for e in graph.get("edges", []):
        src = e.get("from")
        dst = e.get("to")
        if src not in node_set:
            raise ValueError(f"Edge 'from' references unknown node: {src!r}")
        if dst not in node_set:
            raise ValueError(f"Edge 'to' references unknown node: {dst!r}")

    if start_id not in node_set:
        raise ValueError(f"Start node {start_id!r} is missing")

    adj: Dict[str, List[str]] = {}
    for e in graph.get("edges", []):
        adj.setdefault(e["from"], []).append(e["to"])

    seen = {start_id}
    q: deque[str] = deque([start_id])
    while q:
        u = q.popleft()
        for v in adj.get(u, []):
            if v not in seen:
                seen.add(v)
                q.append(v)

    unreachable = sorted(node_set - seen)
    if unreachable:
        raise ValueError(f"Unreachable nodes from start '{start_id}': {unreachable}")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    node_by_id = {n["id"]: n for n in graph.get("nodes", [])}

    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', '\\"')

    out = ["digraph Dialogue {", "  rankdir=LR;"]

    for node_id, n in node_by_id.items():
        ntype = n.get("type", "line")
        shape = "diamond" if ntype == "choice" else "box"
        if ntype == "line":
            speaker = n.get("speaker", "").strip()
            text = n.get("text", "").strip()
            label = f"{node_id}\\n{speaker}: {text}" if speaker or text else node_id
        else:
            label = node_id

        out.append(f'  "{esc(node_id)}" [shape={shape}, label="{esc(label)}"];')

    for e in graph.get("edges", []):
        src = e["from"]
        dst = e["to"]
        label = e.get("text", "")
        if label:
            out.append(f'  "{esc(src)}" -> "{esc(dst)}" [label="{esc(label)}"];')
        else:
            out.append(f'  "{esc(src)}" -> "{esc(dst)}";')

    out.append("}")
    return "\n".join(out) + "\n"


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, ensure_ascii=False, indent=2)
        f.write("\n")

    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(graph_to_dot(graph))


if __name__ == "__main__":
    main()
"}

